<?php
require_once __DIR__.'/bootstrap.php';
require_once __DIR__.'/services/AttainmentImportService.php';
\Services\FeatureManager::requireAccess('MOD_SEE_MARKS');
$service=new \Services\AttainmentImportService();$db=$service->getConnection();
$subject=(int)($_POST['sub_id']??$_GET['sub_id']??0);$component=(int)($_POST['component_id']??$_GET['component_id']??0);
$role=$_SESSION['role'];if(!in_array($role,['faculty','hod','admin','academic_section','superadmin'],true)){\College\RequestSecurity::deny('Staff access required.');}
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$preview=null;$error=$message='';
require_once __DIR__.'/core/SubjectCatalog.php';$subjects=\College\SubjectCatalog::visible($db,$_SESSION);
$components=[];$policy=null;
if($subject){try{$service->assertSubjectScope($subject);$policy=(new \College\AssessmentPolicy($db))->forSubject($subject);$stmt=$db->prepare("SELECT ac.id,ac.component_type FROM assessment_components ac JOIN internal_assessments ia ON ia.id=ac.assessment_id WHERE ia.sub_id=? AND ac.component_type LIKE 'SEE%' ORDER BY ac.id");$stmt->bind_param('i',$subject);$stmt->execute();$components=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);if($component&&!in_array($component,array_map('intval',array_column($components,'id')),true)){throw new DomainException('Choose an external component of this course.');}}catch(Throwable $ex){\College\RequestSecurity::deny($ex->getMessage());}}
if($subject&&isset($_GET['template'])){
    \Services\FeatureManager::requireAction('MOD_SEE_MARKS','export');
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="attainment-template.csv"');$out=fopen('php://output','w');$qs=$component?(new \College\AssessmentPolicy($db))->questions($subject,$component):[];
    fputcsv($out,array_merge(['RollNumber','SubCode'],$component?array_column($qs,'question_label'):['Marks','MaxMarks']));
    $stmt=$db->prepare('SELECT st.username FROM students st JOIN student_sub ss ON ss.stu_id=st.id WHERE ss.sub_id=? ORDER BY st.username');$stmt->bind_param('i',$subject);$stmt->execute();foreach($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $st){fputcsv($out,array_merge([$st['username'],$policy['context']['subcode']],$component?array_fill(0,count($qs),''):['',$policy['config']['net_max']??'']));}fclose($out);exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{\Services\FeatureManager::requireWriteAccess('MOD_SEE_MARKS');
        if(isset($_POST['commit'])){$n=$service->commit((int)$_POST['batch_id'],isset($_POST['replace']),trim($_POST['reason']??''));$message=$n.' records imported. Original evidence and the import audit were retained.';}
        elseif(isset($_POST['preview'])){if(!isset($_FILES['csv'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK||!is_uploaded_file($_FILES['csv']['tmp_name'])){throw new InvalidArgumentException('Choose a CSV file up to 10 MB.');}$preview=$service->stage($subject,$_FILES['csv']['tmp_name'],$component?:null);}
    }catch(Throwable $ex){$error=$ex->getMessage();}
}
$page_title='Import attainment evidence';require __DIR__.'/header.php';$menus=['faculty'=>'facmenu.php','hod'=>'hodmenu.php','admin'=>'adminmenu.php','academic_section'=>'academicsectionmenu.php','superadmin'=>'superadminmenu.php'];if(is_file(__DIR__.'/'.$menus[$role])){require __DIR__.'/'.$menus[$role];}
?>
<div class="container my-4"><h4>Import attainment evidence</h4><p>Upload results from your existing examination system. Matching uses the enrolled roll number and subject code. Other subject codes are skipped and counted; invalid rows prevent the whole import.</p>
<?php if($error):?><div class="alert alert-danger"><?= $e($error) ?></div><?php endif ?><?php if($message):?><div class="alert alert-success"><?= $e($message) ?></div><?php endif ?>
<form method="get" class="row g-2 mb-3"><div class="col-md-8"><label>Course</label><select name="sub_id" class="form-select" required><option value="">Choose course</option><?php foreach($subjects as $s):?><option value="<?= (int)$s['id'] ?>" <?= $subject===(int)$s['id']?'selected':'' ?>><?= $e($s['subcode'].' — '.$s['sub_fullname'].' — '.$s['class_name']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><label>Evidence</label><select name="component_id" class="form-select"><option value="0">Aggregate marks / grades</option><?php foreach($components as $c):?><option value="<?= (int)$c['id'] ?>" <?= $component===(int)$c['id']?'selected':'' ?>>Question-wise: <?= $e($c['component_type']) ?></option><?php endforeach ?></select></div><div class="col-md-1 align-self-end"><button class="btn btn-secondary">Load</button></div></form>
<?php if($subject):?><div class="card card-body mb-3"><p class="small">Aggregate totals estimate CO performance. Question-wise marks measure mapped COs using the selected choice options. Grade-only estimates require an approved grade profile. Gross marks are scaled proportionally to the configured final maximum.</p><p>Final maximum: <strong><?= $e($policy['config']['net_max']??'Supply MaxMarks in CSV') ?></strong>. <a href="?sub_id=<?= $subject ?>&amp;component_id=<?= $component ?>&amp;template=1">Download course template</a></p>
<form method="post" enctype="multipart/form-data"><input type="hidden" name="sub_id" value="<?= $subject ?>"><input type="hidden" name="component_id" value="<?= $component ?>"><label class="form-label">CSV file</label><input class="form-control mb-2" name="csv" type="file" accept=".csv,text/csv" required><button class="btn btn-primary" name="preview">Preview import</button></form>
<details class="mt-3"><summary>Supported columns</summary><p class="small">RollNumber, SubCode; Marks and MaxMarks; optional GrossMarks and GrossMax, Grade and GradePoints. Question-wise templates contain one column per question. Leave unattempted alternatives blank and enter 0 for an assessed zero.</p></details></div><?php endif ?>
<?php if($preview):?><?php foreach($preview['errors'] as $err):?><div class="alert alert-danger"><?= $e($err) ?></div><?php endforeach ?><p><?= count($preview['rows']) ?> valid rows; <?= (int)$preview['skipped_other_courses'] ?> rows from other courses skipped. Showing up to 100 rows.</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Roll number</th><th>Gross</th><th>Gross maximum</th><th>Final marks</th><th>Final maximum</th><th>Evidence</th></tr></thead><tbody><?php foreach(array_slice($preview['rows'],0,100) as $r):?><tr><?php foreach(['roll','raw','raw_max','marks','maximum','basis'] as $key):?><td><?= $e($r[$key]) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div>
<?php if($preview['status']):?><form method="post"><input type="hidden" name="sub_id" value="<?= $subject ?>"><input type="hidden" name="component_id" value="<?= $component ?>"><input type="hidden" name="batch_id" value="<?= (int)$preview['batch_id'] ?>"><label class="d-block"><input type="checkbox" name="replace"> Replace existing marks for these students</label><label class="form-label mt-2">Reason (required for replacement)</label><input class="form-control mb-2" name="reason" maxlength="2000"><button class="btn btn-success" name="commit">Confirm reviewed import</button></form><?php endif ?><?php endif ?></div>
<?php require __DIR__.'/footer.php'; ?>
